Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "width": "container",
  "height": "container",
  "padding": {"top": 6, "left": 4, "right": 12, "bottom": 4},
  "autosize": {"type": "fit", "contains": "padding"},
  "config": {
    "view": {"stroke": null},
    "font": "Segoe UI",
    "background": "transparent"
  },
  "transform": [
    {"calculate": "datum[''Dumbbell CVR %''] != null ? datum[''Dumbbell CVR %''] : (datum[''Conversion Rate %''] != null ? datum[''Conversion Rate %''] : (datum[''CVR''] != null ? datum[''CVR''] : 0))", "as": "cvr_val"},
    {"calculate": "datum[''Channel''] != null ? datum[''Channel''] : (datum[''Channel Grouping''] != null ? datum[''Channel Grouping''] : ''Unknown'')", "as": "channel_name"},
    {"calculate": "datum[''Device''] != null ? datum[''Device''] : (datum[''device_type''] != null ? (lower(datum[''device_type'']) == ''mobile'' ? ''Mobile'' : ''Desktop'') : ''Desktop'')", "as": "device_name"},
    {"filter": "datum.cvr_val > 0 && datum.channel_name != ''Direct Type-In'' && datum.channel_name != ''Paid Social''"},
    {"joinaggregate": [
      {"op": "min", "field": "cvr_val", "as": "minV"},
      {"op": "max", "field": "cvr_val", "as": "maxV"}
    ], "groupby": ["channel_name"]},
    {"calculate": "datum.maxV - datum.minV", "as": "gap"},
    {"calculate": "(datum.minV + datum.maxV) / 2", "as": "mid"},
    {"calculate": "''Δ '' + format(datum.gap * 100, ''.1f'') + '' pp''", "as": "gapTxt"},
    {"joinaggregate": [{"op": "max", "field": "gap", "as": "maxGap"}]},
    {"calculate": "datum.gap === datum.maxGap", "as": "isBiggest"}
  ],
  "encoding": {
    "y": {
      "field": "channel_name", "type": "nominal",
      "scale": {
        "domain": ["Google Nonbrand", "Bing Nonbrand", "Brand (G+B)", "Organic", "Direct", "Social pilot", "Social targeted"],
        "paddingInner": 0.3, "paddingOuter": 0.1
      },
      "axis": {"title": null, "domain": false, "ticks": false, "grid": false,
               "labelColor": "#C9D1E8", "labelFontSize": 12, "labelFontWeight": 600, "labelPadding": 10}
    }
  },
  "layer": [
    {
      "name": "row_track",
      "mark": {"type": "rule", "strokeWidth": 22, "strokeCap": "round", "color": "#141C38", "opacity": 0.6},
      "encoding": {
        "x": {"datum": 0, "type": "quantitative", "scale": {"domain": [0, 0.14], "nice": false}, "axis": null},
        "x2": {"datum": 0.14}
      }
    },
    {
      "name": "dumbbell_connecting_line",
      "mark": {"type": "rule", "strokeWidth": 4, "strokeCap": "round", "color": "#475569", "opacity": 0.9},
      "encoding": {
        "x": {"field": "minV", "type": "quantitative"},
        "x2": {"field": "maxV"},
        "color": {"condition": {"test": "datum.isBiggest", "value": "#FBBF24"}, "value": "#475569"}
      }
    },
    {
      "name": "dumbbell_dots",
      "mark": {"type": "circle", "size": 190, "opacity": 1, "stroke": "#0B1020", "strokeWidth": 2},
      "encoding": {
        "x": {
          "field": "cvr_val", "type": "quantitative",
          "scale": {"domain": [0, 0.14], "nice": false},
          "axis": {"title": null, "values": [0, 0.04, 0.08, 0.12], "format": ".0%", "domain": false, "ticks": false,
                   "grid": true, "gridColor": "#1E293B", "gridDash": [3, 3], "labelColor": "#64748B",
                   "labelFontSize": 10, "labelPadding": 6}
        },
        "color": {
          "field": "device_name", "type": "nominal",
          "scale": {"domain": ["Mobile", "Desktop"], "range": ["#FB7185", "#2DD4BF"]},
          "legend": {"orient": "top-right", "direction": "horizontal", "title": null, "labelColor": "#94A3B8",
                     "labelFontSize": 11, "symbolType": "circle", "symbolSize": 90, "offset": -2}
        },
        "tooltip": [
          {"field": "channel_name", "type": "nominal", "title": "Channel"},
          {"field": "device_name", "type": "nominal", "title": "Device"},
          {"field": "cvr_val", "type": "quantitative", "format": ".2%", "title": "CVR"},
          {"field": "gapTxt", "type": "nominal", "title": "Device gap"}
        ]
      }
    },
    {
      "name": "gap_labels",
      "transform": [{"filter": "datum.device_name == ''Desktop''"}],
      "mark": {"type": "text", "align": "center", "baseline": "bottom", "dy": -9, "fontSize": 10, "fontWeight": 600, "color": "#8B95B0"},
      "encoding": {
        "x": {"field": "mid", "type": "quantitative"},
        "text": {"field": "gapTxt"}
      }
    },
    {
      "name": "mobile_cvr_labels",
      "transform": [{"filter": "datum.device_name == ''Mobile''"}],
      "mark": {"type": "text", "align": "right", "baseline": "middle", "dx": -12, "fontSize": 11, "fontWeight": 700, "color": "#FB7185"},
      "encoding": {
        "x": {"field": "cvr_val", "type": "quantitative"},
        "text": {"field": "cvr_val", "type": "quantitative", "format": ".1%"}
      }
    },
    {
      "name": "desktop_cvr_labels",
      "transform": [{"filter": "datum.device_name == ''Desktop''"}],
      "mark": {"type": "text", "align": "left", "baseline": "middle", "dx": 12, "fontSize": 11, "fontWeight": 700, "color": "#2DD4BF"},
      "encoding": {
        "x": {"field": "cvr_val", "type": "quantitative"},
        "text": {"field": "cvr_val", "type": "quantitative", "format": ".1%"}
      }
    }
  ]
}'
